double h = b - a;
double I0 = (f(a) + f(b)) * h / 2.0;
double I1 = 0.0;
double error = 0.0;

do {
    // Compute refined trapezoidal approximation
    double sum = 0.0;
    for (int i = 1; i < static_cast<int>(1 << 10); i += 2) { // Use a reasonable max subdivisions
        sum += f(a + i * h / (1 << 10));
    }
    I1 = (I0 / 2.0) + (h / (1 << 10)) * sum;

    // Error estimation via Richardson extrapolation
    error = std::abs(I1 - I0) / 3.0;

    // Update for next iteration
    I0 = I1;
    h /= 2.0;
} while (error > precision);

return I1;

